#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int visiblePoints(vector<vector<int>>& points, int angle,
                      vector<int>& location) {
        const double PI = acos(-1.0), EPS = 1e-10;
        vector<double> a;
        int same = 0;
        for (auto& p : points) {
            int x = p[0] - location[0], y = p[1] - location[1];
            if (x == 0 && y == 0) ++same;
            else a.push_back(atan2((double)y, (double)x));
        }
        sort(a.begin(), a.end());
        int n = a.size();
        for (int i = 0; i < n; ++i) a.push_back(a[i] + 2 * PI);
        double width = angle * PI / 180.0;
        int best = 0;
        for (int l = 0, r = 0; l < n; ++l) {
            if (r < l) r = l;
            while (r < l + n && a[r] - a[l] <= width + EPS) ++r;
            best = max(best, r - l);
        }
        return best + same;
    }
};
